<?php
/** TEMP PS S1675 run f — base.php v2.13 deploy (AVPN tik invoice) + #35902 AVPN011016 nuėmimas + patikra. FIND/APPLY. */
add_action('init', function(){
  if (!isset($_GET['ps_f5'])) return; $f=$_GET['ps_f5']; global $wpdb; $p=$wpdb->prefix; $o=array('v'=>'S1675 f','faze'=>$f);
  $o['temp_istrinta']=(int)$wpdb->query("DELETE FROM {$p}snippets WHERE name LIKE 'TEMP%' AND active=0");
  $g=array_merge(glob(get_stylesheet_directory().'/*/base.php'),glob(get_stylesheet_directory().'/*/*/base.php'),glob(get_stylesheet_directory().'/base.php'));
  $o['rasta']=array(); foreach($g as $x) $o['rasta'][str_replace(ABSPATH,'',$x)]=md5_file($x);
  $new=gzdecode(base64_decode('')); $o['new_md5']=md5($new);
  if($f!=='APPLY'){ header('Content-Type: application/json'); echo json_encode($o,JSON_UNESCAPED_UNICODE); exit; }
  if(count($g)!==1 || md5_file($g[0])!=='4b865eef60ee9405cb58de4f51864d88'){ $o['stop']='kelias/md5 nesutampa'; header('Content-Type: application/json'); echo json_encode($o,JSON_UNESCAPED_UNICODE); exit; }
  try{ token_get_all($new,TOKEN_PARSE); }catch(Throwable $e){ $o['stop']='parse '.$e->getMessage(); header('Content-Type: application/json'); echo json_encode($o); exit; }
  $bak=WP_CONTENT_DIR.'/uploads/ps-backups/base.php.bak_s1675'; copy($g[0],$bak); $o['bak']=md5_file($bak);
  file_put_contents($g[0],$new); $o['irasyta_md5']=md5_file($g[0]);
  $o['ping']=wp_remote_retrieve_response_code(wp_remote_get(home_url('/'),array('timeout'=>30,'sslverify'=>false)));
  if($o['ping']>=500){ copy($bak,$g[0]); $o['rollback']=md5_file($g[0]); }
  // #35902: AVPN nuimti
  $w=wc_get_order(35902); if($w && !$w->is_paid()){ $w->delete_meta_data('_petshop_avpn_number'); $w->add_order_note('S1675: AVPN011016 nuimtas — priskirtas neapmokėtam (base.php v2.12 klaida: AVPN kvietė prieš tipo nustatymą; v2.13 pataisyta). PVM sąskaita bus išrašyta apmokėjus.',false,true); $w->save(); $o['o35902_avpn_po']=(string)wc_get_order(35902)->get_meta('_petshop_avpn_number'); }
  $o['counter']=get_option('petshop_avpn_counter');
  header('Content-Type: application/json'); echo json_encode($o,JSON_UNESCAPED_UNICODE); exit;
},99);
